/**
 * Security Alert Controller
 * Retrieves and filters security alerts generated by FSM analysis.
 * Academic Project: Network Event Log Analyzer
 */

const mongoose = require('mongoose');
const SecurityAlert = require('../models/SecurityAlert');
const { memoryStore } = require('../utils/memoryStore');

function isDbConnected() {
  return mongoose.connection.readyState === 1;
}

/**
 * GET /api/alerts
 * Retrieve paginated alerts with search and severity filter.
 */
async function getAlerts(req, res, next) {
  try {
    const { search, severity, page = 1, limit = 20 } = req.query;
    const pageNum = Math.max(1, parseInt(page, 10) || 1);
    const limitNum = Math.min(100, Math.max(1, parseInt(limit, 10) || 20));
    const skip = (pageNum - 1) * limitNum;

    if (isDbConnected()) {
      const query = {};

      if (search && search.trim()) {
        const regex = new RegExp(search.trim(), 'i');
        query.$or = [{ ipAddress: regex }, { message: regex }];
      }

      if (severity && severity.toUpperCase() !== 'ALL') {
        query.severity = severity.toUpperCase();
      }

      const total = await SecurityAlert.countDocuments(query);
      const alerts = await SecurityAlert.find(query)
        .sort({ timestamp: -1 })
        .skip(skip)
        .limit(limitNum)
        .lean();

      return res.status(200).json({
        success: true,
        count: alerts.length,
        total,
        page: pageNum,
        totalPages: Math.ceil(total / limitNum) || 1,
        data: alerts
      });
    }

    // In-memory fallback
    const memAlerts = memoryStore.getAlerts({
      search,
      severity,
      page: pageNum,
      limit: limitNum
    });

    res.status(200).json({
      success: true,
      ...memAlerts
    });
  } catch (error) {
    next(error);
  }
}

module.exports = {
  getAlerts
};
